def run(directory,spec_path):
    directory=Path(directory);spec_path=Path(spec_path);assert not directory.exists();directory.mkdir();began=time.monotonic();deadline=began+900;train_deadline=began+400;spec=base.read(spec_path);base.atomic_json(directory/'work-clock.json',dict(started_wall_ns=time.time_ns(),started_monotonic=began,deadline_monotonic=deadline,training_deadline_monotonic=train_deadline,seconds=900,training_max_seconds=400,implementation_seconds_separate_estimate=spec['implementation_seconds_separate_estimate']));(directory/'spec.json').write_bytes(spec_path.read_bytes());source=base.source_signature();files={n:base.sha(Path(__file__).with_name(n)) for n in FILES};bank=base.read(spec['bank']);assert base.sha(spec['bank'])==spec['bank_sha256'] and source==bank['source']
    for p,digest in spec['pinned_assets'].items():assert base.sha(p)==digest
    initial=load_readout(bank['current_model_bundle']);current=initial;current_root=Path(bank['current_head']).parent;byseed={e['seed']:e for e in bank['bank']};baseline={s:base.read(e['receipt']) for s,e in byseed.items()};B=correction_basis(VisualStateEncoder(64,64,.02).layout,4389);B.flags.writeable=False;base.save_array(directory/'correction-basis.npy',B);den=np.load(spec['raw_denominator']);G=np.load(spec['metric'],mmap_mode='r');H=projected_metric(G,B,den);L=la.cholesky(H,lower=True,check_finite=False);base.save_array(directory/'projected-metric.npy',H);X=sp.load_npz(spec['calibration_raw']);F=np.asarray(X@B.T);q0=exact_q(initial,X);q=q0.copy();calib=base.read(spec['calibration']);temperature=calib['temperature'];initial_rms=calib['initial_centered_q_rms'];assert abs(np.sqrt(np.mean((q0-q0.mean(1,keepdims=True))**2))-initial_rms)<1e-12;assert abs(np.mean(1-probabilities(q0,temperature)[np.arange(len(q0)),np.argmax(q0,1)])-.05)<1e-10;jobs=base.read(spec['training_schedule'])['batches'];scheduled={j['seed'] for batch in jobs for j in batch};assert len(jobs)==32 and all(len(batch)==4 for batch in jobs) and len(scheduled)==64
    manifest=dict(source=source,files=files,spec_sha256=base.sha(spec_path),basis_sha256=base.sha(directory/'correction-basis.npy'),projected_metric_sha256=base.sha(directory/'projected-metric.npy'),initial_policy_sha256=bank['current_policy_sha256'],initial_base_sha256=bank['current_head_sha256'],trainable_contrast_coordinates=396,non_grid_and_high_frequency_W_frozen=True,entire_pairwise_R_fixed=True,metric='J=[B*rawden,0]; H=JGJ.T; no new ridge or whitening',temperature=temperature,initial_centered_q_rms=initial_rms,selection='FINAL completed batch only',screen='fixed128, all64scheduledtraining plus64otherbankphase/depthbalanced; before outcomes',training_max_seconds=400,maximum_training_transition_cameras=64000,no_new_architecture_or_inputs=True,no_backprop=True,no_historical_action_locks=True)
    base.atomic_json(directory/'manifest.json',manifest);base.atomic_json(directory/'training-schedule.json',base.read(spec['training_schedule']));base.atomic_json(directory/'screen-schedule.json',dict(seeds=spec['screen'],scheduled_training=sorted(scheduled),other_controls=[s for s in spec['screen'] if s not in scheduled],selection=spec['screen_selection']));summary=dict(status='preparing_smooth_actor',new_transition_cameras=0,new_initial_cameras=0,training_transition_cameras=0,training_initials=0,accepted_batches=0)
